package com.hostel.hostelmanagement.controller; import com.hostel.hostelmanagement.dto.NoticeRequest; import com.hostel.hostelmanagement.entity.Notice; import com.hostel.hostelmanagement.repository.NoticeRepository; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/notices") public class NoticeController {final NoticeRepository r;public NoticeController(NoticeRepository r){this.r=r;}@GetMapping Object all(){return r.findAll();}@PostMapping Notice add(@RequestBody NoticeRequest x){Notice n=new Notice();n.setTitle(x.getTitle());n.setContent(x.getContent());return r.save(n);}}